import React, {useEffect, useState} from 'react';
import { useParams, Link } from 'react-router-dom';
import { getObra } from '../../services/api';

export default function Details(){
  const { id } = useParams();
  const [obra, setObra] = useState(null);
  const [loading, setLoading] = useState(false);

  useEffect(()=>{
    (async ()=>{
      setLoading(true);
      try{
        const res = await getObra(id);
        setObra(res.data);
      }catch(err){
        console.error(err);
        alert('Erro ao carregar detalhes.');
      }finally{
        setLoading(false);
      }
    })();
  },[id]);

  if(loading) return <p>Carregando...</p>;
  if(!obra) return <p>Obra não encontrada.</p>;

  return (
    <div style={{background:'#fff',padding:16,borderRadius:8}}>
      <h2>{obra.titulo}</h2>
      <p><strong>{obra.tipo}</strong> • {obra.genero} • {obra.ano || '—'}</p>
      <p>Status: {obra.status}</p>
      <p>Avaliação: {obra.avaliacao || '—'}</p>
      {obra.imagem && <img src={obra.imagem} alt={obra.titulo} style={{maxWidth:300,borderRadius:8,marginTop:8}} />}
      <p style={{marginTop:12}}>{obra.descricao}</p>
      <p style={{marginTop:12}}><Link to={`/edit/${obra._id || obra.id}`}>Editar</Link></p>
    </div>
  );
}
